/**
 * Test Data Fixtures
 *
 * Provides factory functions and mock data for testing.
 * Use these fixtures to create consistent test data across test files.
 *
 * Usage:
 *   import { createMockProduct, createMockCategory } from '@/__tests__/fixtures/test-data'
 *
 *   test('displays product', () => {
 *     const product = createMockProduct({ name: 'Test Product' })
 *     // Use product in test
 *   })
 */

import type {
  Product,
  Category,
  RestaurantTable,
  Organization,
  OrganizationMember,
  Plan,
  Feature,
  PlanFeature,
  PriceLedgerEntry,
  CurrentPrice,
  UserRole,
} from '@/types'

/**
 * Create a mock organization with optional overrides
 */
export function createMockOrganization(
  overrides: Partial<Organization> = {}
): Organization {
  const now = new Date().toISOString()
  return {
    id: 'org-' + Math.random().toString(36).substring(7),
    name: 'Test Restaurant',
    slug: 'test-restaurant',
    is_active: true,
    created_at: now,
    updated_at: now,
    ...overrides,
  }
}

/**
 * Create a mock organization member with optional overrides
 */
export function createMockMember(
  overrides: Partial<OrganizationMember> = {}
): OrganizationMember {
  const now = new Date().toISOString()
  return {
    id: 'member-' + Math.random().toString(36).substring(7),
    organization_id: 'org-test',
    user_id: 'user-test',
    role: 'owner' as UserRole,
    created_at: now,
    updated_at: now,
    ...overrides,
  }
}

