    nutritional_info: null,
    preparation_time_minutes: null,
    is_available: true,
    created_at: now,
    updated_at: now,
    ...overrides,
  }
}

/**
 * Create a mock price ledger entry with optional overrides
 */
export function createMockPriceLedgerEntry(
  overrides: Partial<PriceLedgerEntry> = {}
): PriceLedgerEntry {
  return {
    id: 'price-' + Math.random().toString(36).substring(7),
    product_id: 'prod-test',
    price: 99.99,
    currency: 'TRY',
    change_reason: 'Initial price',
    changed_by: 'user-test',
    created_at: new Date().toISOString(),
    ...overrides,
