/**
 * Create multiple mock products
 *
 * @param count - Number of products to create
 * @param overrides - Common overrides to apply to all products
 * @returns Array of mock products
 */
export function createMockProducts(
  count: number,
  overrides: Partial<Product> = {}
): Product[] {
  return Array.from({ length: count }, (_, i) =>
    createMockProduct({
      name: `Product ${i + 1}`,
      slug: `product-${i + 1}`,
      ...overrides,
    })
  )
}

/**
 * Create multiple mock categories
 *
 * @param count - Number of categories to create
 * @param overrides - Common overrides to apply to all categories
 * @returns Array of mock categories
 */
export function createMockCategories(
  count: number,
  overrides: Partial<Category> = {}
): Category[] {
  return Array.from({ length: count }, (_, i) =>
    createMockCategory({
      name: `Category ${i + 1}`,
      slug: `category-${i + 1}`,
      sort_order: i,
      ...overrides,
    })
  )
}

/**
 * Create multiple mock tables
 *
 * @param count - Number of tables to create
 * @param overrides - Common overrides to apply to all tables
 * @returns Array of mock tables
 */
export function createMockTables(
  count: number,
  overrides: Partial<RestaurantTable> = {}
): RestaurantTable[] {
  return Array.from({ length: count }, (_, i) =>
    createMockTable({
      table_number: i + 1,
      qr_code_url: `https://example.com/qr/table-${i + 1}.png`,
      ...overrides,
    })
  )
}

/**
 * Create multiple mock plans
 *
 * @param count - Number of plans to create
 * @param overrides - Common overrides to apply to all plans
 * @returns Array of mock plans
 */
export function createMockPlans(count: number, overrides: Partial<Plan> = {}): Plan[] {
  return Array.from({ length: count }, (_, i) =>
    createMockPlan({
      name: `Plan ${i + 1}`,
      slug: `plan-${i + 1}`,
      price_monthly: (i + 1) * 99.99,
      price_yearly: (i + 1) * 999.99,
      sort_order: i,
      ...overrides,
    })
  )
}

/**
 * Create a hierarchical category tree for testing
 *
 * @returns Object with parent and child categories
 */
export function createMockCategoryTree() {
  const parent = createMockCategory({
    name: 'Parent Category',
    slug: 'parent-category',
    parent_id: null,
  })

  const children = [
    createMockCategory({
      name: 'Child Category 1',
      slug: 'child-category-1',
      parent_id: parent.id,
    }),
    createMockCategory({
      name: 'Child Category 2',
      slug: 'child-category-2',
      parent_id: parent.id,
    }),
  ]

  return { parent, children }
}

/**
 * Create a product with price history for testing
 *
 * @param priceChanges - Number of price changes to generate
 * @returns Object with product and price history
 */
export function createMockProductWithPriceHistory(priceChanges = 3) {
  const product = createMockProduct()
  const history: PriceLedgerEntry[] = []
  const baseDate = new Date('2024-01-01')

  for (let i = 0; i < priceChanges; i++) {
    const date = new Date(baseDate)
    date.setMonth(date.getMonth() + i)

    history.push(
      createMockPriceLedgerEntry({
        product_id: product.id,
        price: 50 + i * 10,
        change_reason: i === 0 ? 'Initial price' : `Price adjustment ${i}`,
        created_at: date.toISOString(),
      })
    )
  }

  const currentPrice = createMockCurrentPrice({
    product_id: product.id,
    price: history[history.length - 1].price,
    created_at: history[history.length - 1].created_at,
  })

  return { product, history, currentPrice }
}
